#include <IQM/hdrvdp3/pathway_quality.h>
#include <vulkan_instance.h>
#include <algorithm>
#include <bit>
#include <cmath>
#include <fstream>
#include <iomanip>
#include <iostream>
#include <map>
#include <stdexcept>
#include <type_traits>
namespace fs=std::filesystem;
template<class T>std::vector<T> read(const fs::path& path){std::ifstream f(path);unsigned h,w;if(!(f>>h>>w)||!h||!w||size_t(h)*w>1000000)throw std::runtime_error("Invalid fixture:"+path.string());std::vector<T> v(size_t(h)*w);for(auto& x:v)if(!(f>>x)||!std::isfinite(double(x)))throw std::runtime_error("Invalid value:"+path.string());std::string extra;if(f>>extra)throw std::runtime_error("Trailing fixture values");return v;}
int main(int argc,char** argv){try{
 if(argc!=3 && argc!=4)throw std::runtime_error("Usage:case-config fresh-output [--repeat]");const bool repeat=argc==4;if(repeat && std::string(argv[3])!="--repeat")throw std::runtime_error("Unknown option");std::ifstream config(argv[1]);if(!config)throw std::runtime_error("Missing case config");std::map<std::string,std::string> c;std::string key,value;while(config>>key>>std::quoted(value))if(!c.emplace(key,value).second)throw std::runtime_error("Duplicate config key");if(!config.eof()||c.size()!=22)throw std::runtime_error("Invalid config");
 const fs::path out(argv[2]);if(fs::exists(out)||!fs::create_directories(out))throw std::runtime_error("Fresh output required");const unsigned w=std::stoul(c.at("w")),h=std::stoul(c.at("h"));const std::string tag="h"+std::to_string(h)+"_w"+std::to_string(w);
 const fs::path nf=fs::path(c.at("native_filters"))/tag,nv=c.at("native_visual"),ns=c.at("native_spyr"),nm=fs::path(c.at("native_masking"))/tag,nr=fs::path(c.at("native_residual"))/tag,nc=fs::path(c.at("native_comparison"))/(tag+"_p0");
 IQM::HDRVDP3::PathwayQualityAssets assets{{c.at("forward"),c.at("inverse"),c.at("io")},{c.at("spyr_fma"),c.at("spyr_separate"),c.at("mean"),c.at("difference"),c.at("residual")},{read<uint32_t>(ns/"lo0.txt"),read<uint32_t>(ns/"lo.txt"),read<uint32_t>(ns/"hi0.txt"),read<uint32_t>(ns/"orient.txt")},{c.at("pool_fma"),c.at("pool_separate")},c.at("comparison"),{c.at("map"),c.at("product"),c.at("base")}};
 const auto reference=read<float>(nf/"ref_luminance.txt"),test=read<float>(nf/"test_luminance.txt");IQM::Bin::VulkanInstance instance(true);IQM::HDRVDP3::PathwayQualityTrace trace;
 const auto scores=IQM::HDRVDP3::evaluate_pathway_quality(instance,reference,test,w,h,assets,&trace);
 std::ofstream results(out/"results.tsv");results<<"stage\tvalues\tbit_errors\n";size_t checks=0,total=0;
 auto check=[&]<class T>(const std::string& name,const std::vector<T>& actual,const std::vector<T>& expected){if(actual.size()!=expected.size())throw std::runtime_error("Shape mismatch:"+name);size_t bad=0;for(size_t i=0;i<actual.size();++i){if constexpr(std::is_floating_point_v<T>){using U=std::conditional_t<sizeof(T)==4,uint32_t,uint64_t>;bad+=std::bit_cast<U>(actual[i])!=std::bit_cast<U>(expected[i]);}else bad+=actual[i]!=expected[i];}results<<name<<'\t'<<actual.size()<<'\t'<<bad<<'\n';results.flush();std::ofstream dump(out/(name+".bin"),std::ios::binary);dump.write(reinterpret_cast<const char*>(actual.data()),actual.size()*sizeof(T));++checks;total+=actual.size();if(bad)throw std::runtime_error("Exact parity failure:"+name+", words="+std::to_string(bad));};
 for(unsigned image=0;image<2;++image){const std::string label=image?"test":"reference";const auto folder=nv/"stages"/tag;check(label+"_retinal",trace.retinal[image],read<float>(folder/(label+"_retinal.txt")));check(label+"_adaptation",trace.adaptation[image],read<float>(folder/(label+"_adaptation.txt")));check(label+"_P",trace.P[image],read<float>(folder/(label+"_P.txt")));}
 check("log_adaptation",trace.logAdaptation,read<float>(nv/tag/"log_La.txt"));
 for(unsigned j=0;j<11;++j){std::vector<uint32_t> expected;if(j<8){const std::string name=j<4?"stage"+std::to_string(j)+".txt":j==4?"high.txt":"orient"+std::to_string(j-5)+".txt";expected=read<uint32_t>(ns/(tag+"_reference")/name);auto t=read<uint32_t>(ns/(tag+"_test")/name);expected.insert(expected.end(),t.begin(),t.end());}else expected=read<uint32_t>(nr/(j==8?"mean.txt":j==9?"difference_pack_words.txt":"difference_expected_words.txt"));check("spyr"+std::to_string(j),trace.spyr.stages[j],expected);}
 const auto binary=read<uint32_t>(nc/"binary.txt");const auto errors=read<float>(nm/"errors.txt");
 for(unsigned b=0;b<5;++b){const std::string band="band"+std::to_string(b+1);auto golden=[&](const std::string& field){return read<float>(nm/(band+"_"+field+".txt"));};const auto r=golden("reference"),t=golden("test");auto raw=r;for(size_t i=0;i<raw.size();++i)raw[i]=std::min(std::abs(r[i]),std::abs(t[i]));check(band+"_raw",trace.pool[b].raw,raw);check(band+"_pooled",trace.pool[b].pooled,golden("self"));check(band+"_binary",trace.comparison[b].binary,binary);check(band+"_comparison",trace.comparison[b].resized,read<double>(nm/(band+"_comparison.txt")));
 const auto& a=trace.masking.bands[b];check(band+"_neighbor",a.neighbor,golden("neighbor"));check(band+"_denominator",a.denominator,golden("denominator"));auto diff=r;for(size_t i=0;i<diff.size();++i)diff[i]=t[i]-r[i];check(band+"_band_difference",a.difference,diff);check(band+"_csf",a.sensitivity,golden("csf"));check(band+"_D",a.D,golden("difference"));check(band+"_psychometric",a.psychometric,golden("psychometric"));check(band+"_masked",a.masked,golden("quality_difference"));check(band+"_error",std::vector<float>{a.error},std::vector<float>{errors.at(b)});
 }
 const auto base=read<double>(nv/tag/"base_selection.txt");if(base.size()!=4)throw std::runtime_error("Base golden shape");double sum=0;for(float x:trace.masking.baseLog)sum+=double(x);check("base_adaptation",trace.masking.baseAdaptation,std::vector<float>{float(sum/120.0),float(base[2])});check("base_noise",std::vector<double>{trace.masking.baseNoise.begin(),trace.masking.baseNoise.end()},std::vector<double>{base[0]-1,base[1],base[3]});check("scores",std::vector<float>{scores.Q,scores.Q_JOD},read<float>(nm/"scores.txt"));
 if(repeat){const auto plain=IQM::HDRVDP3::evaluate_pathway_quality(instance,reference,test,w,h,assets);check("scores_no_trace",std::vector<float>{plain.Q,plain.Q_JOD},std::vector<float>{scores.Q,scores.Q_JOD});}if(checks!=(repeat?82u:81u))throw std::runtime_error("Incomplete stage coverage");
 std::ofstream(out/"PASS.txt")<<"Single in-memory original-image quality API:actual checks in scores.json,"<<total<<" words bitwise exact.\n";std::ofstream(out/"scores.json")<<std::setprecision(17)<<"{\"Q\":"<<scores.Q<<",\"Q_JOD\":"<<scores.Q_JOD<<",\"stage_checks\":"<<checks<<",\"values\":"<<total<<"}";std::cout<<"In-memory quality PASS:"<<tag<<" checks="<<checks<<" values="<<total<<'\n';return 0;
 }catch(const std::exception& e){std::cerr<<e.what()<<'\n';return 1;}}
